INSERT INTO public.labs (slug,title,category,difficulty,points,description,engine,docker_image,lesson_path,estimated_minutes,author_id,tags)
SELECT v.slug,v.title,v.category,v.diff::public.lab_difficulty,v.pts,v.descr,v.engine,v.img,v.path,v.mins,a.id,'{}'::text[] FROM (VALUES
('sql-injection-fundamentals','SQL Injection Fundamentals','Web Application Security','Beginner',100,'Your first hands-on look at classical SQL injection.','OWASP WebGoat','webgoat/webgoat:latest','WebGoat/SqlInjection',25,'OWASP WebGoat Team'),
('blind-sqli-time','Blind SQL Injection (Time-Based)','Web Application Security','Intermediate',200,'The application no longer echoes database errors and returns identical pages for valid and invalid requests.','OWASP WebGoat','webgoat/webgoat:latest','WebGoat/SqlInjectionAdvanced',45,'OWASP WebGoat Team'),
('reflected-xss','Reflected Cross-Site Scripting','Web Application Security','Beginner',100,'The search parameter is reflected into the page without encoding.','OWASP Juice Shop','bkimminich/juice-shop:latest','JuiceShop/XssTier1',25,'OWASP Juice Shop Team'),
('stored-xss-reviews','Stored XSS in Product Reviews','Web Application Security','Intermediate',200,'Reviews are stored server-side and rendered to every visitor.','OWASP Juice Shop','bkimminich/juice-shop:latest','JuiceShop/XssTier3',40,'OWASP Juice Shop Team'),
('csrf-profile-update','CSRF on Profile Update','Web Application Security','Intermediate',150,'The profile-update endpoint accepts requests without a token or origin check.','OWASP WebGoat','webgoat/webgoat:latest','WebGoat/CSRF',30,'OWASP WebGoat Team'),
('idor-invoice','Insecure Direct Object Reference — Invoices','Web Application Security','Beginner',100,'The invoice endpoint uses a numeric identifier in the URL and no ownership check.','DVWA','vulnerables/web-dvwa:latest','DVWA/IDOR',25,'DVWA Maintainers'),
('xxe-upload','XML External Entity in File Upload','Web Application Security','Intermediate',200,'The upload endpoint parses XML with external entities enabled.','OWASP WebGoat','webgoat/webgoat:latest','WebGoat/XXE',40,'OWASP WebGoat Team'),
('ssrf-metadata','Server-Side Request Forgery to Cloud Metadata','Web Application Security','Advanced',300,'The ''fetch preview'' feature takes a URL and returns the response body.','OWASP WebGoat','webgoat/webgoat:latest','WebGoat/SSRF',50,'OWASP WebGoat Team'),
('path-traversal-download','Path Traversal in Downloads','Web Application Security','Beginner',100,'The download endpoint takes a filename and reads it from a directory.','DVWA','vulnerables/web-dvwa:latest','DVWA/FileInclusion',25,'DVWA Maintainers'),
('insecure-deserialization','Insecure Deserialization','Web Application Security','Advanced',300,'The session cookie is a serialized Java object.','OWASP WebGoat','webgoat/webgoat:latest','WebGoat/InsecureDeserialization',55,'OWASP WebGoat Team'),
('unrestricted-upload','Unrestricted File Upload','Web Application Security','Intermediate',200,'The upload endpoint trusts the client-provided extension.','DVWA','vulnerables/web-dvwa:latest','DVWA/FileUpload',35,'DVWA Maintainers'),
('open-redirect','Open Redirect in Login Flow','Web Application Security','Beginner',75,'The login flow accepts a `next` parameter and redirects to it verbatim.','Custom Docker Lab','webkeet/open-redirect:latest','webkeet/openredirect',20,'WebKeet Lab Team'),
('clickjacking-basics','Clickjacking on Account Deletion','Web Application Security','Beginner',75,'The account-settings page has no framing protection.','Custom Docker Lab','webkeet/clickjack:latest','webkeet/clickjacking',20,'WebKeet Lab Team'),
('broken-auth-bypass','Broken Authentication Bypass','Authentication and Session','Intermediate',200,'The application distinguishes users by a hidden form field returned after login.','OWASP WebGoat','webgoat/webgoat:latest','WebGoat/Authentication',35,'OWASP WebGoat Team'),
('jwt-none-algorithm','JWT `none` Algorithm Abuse','Authentication and Session','Intermediate',200,'The API accepts JWTs with the `none` algorithm because the verifier is misconfigured.','crAPI','owasp/crapi:latest','crapi/jwt',30,'crAPI Project'),
('oauth-redirect-uri','OAuth Redirect URI Misconfiguration','Authentication and Session','Advanced',300,'The OAuth provider does a prefix match on the registered redirect URI.','Custom Docker Lab','webkeet/oauth-lab:latest','webkeet/oauth',45,'WebKeet Cloud Guild'),
('password-reset-token','Predictable Password Reset Token','Authentication and Session','Intermediate',200,'The reset token is derived from the user id and a timestamp with second precision.','Custom Docker Lab','webkeet/reset-token:latest','webkeet/reset',30,'WebKeet Lab Team'),
('bola-crapi','BOLA — Broken Object Level Authorization','API Security','Intermediate',200,'The vehicle-details endpoint checks that the caller is authenticated but not that they own the requested vehicle.','crAPI','owasp/crapi:latest','crapi/bola',35,'crAPI Project'),
('mass-assignment','Mass Assignment Elevation','API Security','Intermediate',200,'The profile-update endpoint binds the entire request body to the user model — including the `role` field.','OWASP NodeGoat','owasp/nodegoat:latest','nodegoat/mass-assignment',35,'OWASP NodeGoat Team'),
('rate-limit-bypass','API Rate Limit Bypass','API Security','Beginner',100,'The login endpoint rate-limits by trusting the `X-Forwarded-For` header directly.','crAPI','owasp/crapi:latest','crapi/rate-limit',25,'crAPI Project'),
('graphql-introspection','GraphQL Introspection Abuse','API Security','Advanced',300,'Introspection is enabled in production, exposing every type and field.','Custom Docker Lab','webkeet/graphql-lab:latest','webkeet/graphql',45,'WebKeet Lab Team'),
('coupon-race','Coupon Race Condition','Access Control and Business Logic','Advanced',300,'The coupon-redemption endpoint checks for prior use, then records it — a classic time-of-check to time-of-use bug.','OWASP Juice Shop','bkimminich/juice-shop:latest','juiceshop/coupon-race',40,'OWASP Juice Shop Team'),
('privilege-escalation-vertical','Vertical Privilege Escalation','Access Control and Business Logic','Intermediate',200,'The admin route is hidden but not gated.','OWASP WebGoat','webgoat/webgoat:latest','WebGoat/AccessControl',30,'OWASP WebGoat Team'),
('cart-price-tampering','Cart Price Tampering','Access Control and Business Logic','Intermediate',200,'The checkout endpoint accepts a `price` field from the client and trusts it.','OWASP Juice Shop','bkimminich/juice-shop:latest','juiceshop/price-tampering',30,'OWASP Juice Shop Team'),
('weak-md5','Weak MD5 Password Hashing','Cryptography','Beginner',100,'The user table stores unsalted MD5 password hashes.','Custom Docker Lab','webkeet/md5-lab:latest','webkeet/crypto/md5',25,'WebKeet Lab Team'),
('ecb-mode','ECB Mode Pattern Leak','Cryptography','Intermediate',200,'An admin cookie is AES-encrypted in ECB mode.','Custom Docker Lab','webkeet/ecb-lab:latest','webkeet/crypto/ecb',30,'WebKeet Lab Team'),
('padding-oracle','Padding Oracle Basics','Cryptography','Advanced',300,'A CBC-mode endpoint returns distinguishable errors for padding versus content failures.','Custom Docker Lab','webkeet/padding-oracle:latest','webkeet/crypto/padding-oracle',50,'WebKeet Lab Team'),
('predictable-random','Predictable Random Session Token','Cryptography','Intermediate',200,'Session tokens are generated with `Math.random()`.','Custom Docker Lab','webkeet/prng-lab:latest','webkeet/crypto/prng',30,'WebKeet Lab Team'),
('exposed-bucket','Exposed Object Storage Bucket','Cloud and Container Security','Beginner',100,'A staging bucket is configured for public list-and-read.','Custom Docker Lab','webkeet/bucket-lab:latest','webkeet/cloud/bucket',25,'WebKeet Cloud Guild'),
('docker-socket','Docker Socket Mounted into Container','Cloud and Container Security','Advanced',300,'A container has `/var/run/docker.sock` mounted read-write.','Custom Docker Lab','webkeet/docker-socket:latest','webkeet/cloud/docker-socket',50,'WebKeet Cloud Guild'),
('iam-over-permissive','Over-Permissive IAM Policy','Cloud and Container Security','Intermediate',200,'A service role is attached with `*:*` permissions.','Custom Docker Lab','webkeet/iam-lab:latest','webkeet/cloud/iam',35,'WebKeet Cloud Guild'),
('git-secrets','Secrets Committed to Git History','Cloud and Container Security','Beginner',100,'A live API key was removed from HEAD but still sits in the git history.','Custom Docker Lab','webkeet/git-secrets:latest','webkeet/cloud/git',25,'WebKeet Cloud Guild'),
('suid-abuse','SUID Binary Abuse','Linux and Network Basics','Intermediate',200,'A helper binary was marked SUID root to ''save time''.','Custom Docker Lab','webkeet/linux-suid:latest','webkeet/linux/suid',35,'WebKeet Lab Team'),
('cron-hijack','Cron Script Hijack','Linux and Network Basics','Intermediate',200,'Root runs a group-writable backup script every minute.','Custom Docker Lab','webkeet/linux-cron:latest','webkeet/linux/cron',35,'WebKeet Lab Team'),
('nmap-discovery','Nmap Discovery Basics','Linux and Network Basics','Beginner',100,'An isolated subnet hides several services from the intended user.','Custom Docker Lab','webkeet/nmap-lab:latest','webkeet/linux/nmap',25,'WebKeet Lab Team'),
('sudo-root','Sudo Misconfiguration to Root','Linux and Network Basics','Advanced',300,'A sudoers rule grants NOPASSWD to a binary that can execute arbitrary commands.','Custom Docker Lab','webkeet/linux-sudo:latest','webkeet/linux/sudo',40,'WebKeet Lab Team'),
('scr-sqli','Find the SQLi in the Diff','Secure Code Review','Intermediate',150,'A pull request quietly switches a parameterized query to string interpolation.','Custom Docker Lab','webkeet/code-review:latest','webkeet/scr/sqli',25,'WebKeet Lab Team'),
('scr-csrf','Fix the Broken CSRF Guard','Secure Code Review','Intermediate',150,'The CSRF middleware only covers POST requests.','Custom Docker Lab','webkeet/code-review:latest','webkeet/scr/csrf',25,'WebKeet Lab Team'),
('scr-upload','Review a Vulnerable File Upload','Secure Code Review','Advanced',200,'A resume-upload pull request hides three separate bugs.','Custom Docker Lab','webkeet/code-review:latest','webkeet/scr/upload',35,'WebKeet Lab Team'),
('access-log-timeline','Access Log Timeline','Forensics and Logs','Beginner',100,'Reconstruct an account takeover from a day of web-server access logs.','Custom Docker Lab','webkeet/logs-lab:latest','webkeet/blue/timeline',30,'WebKeet Blue Team'),
('web-shell-upload','Spot the Web Shell Upload','Forensics and Logs','Intermediate',200,'Access logs contain an upload followed by unusual GET requests to the uploaded path.','Custom Docker Lab','webkeet/logs-lab:latest','webkeet/blue/shell',35,'WebKeet Blue Team'),
('exfil-iocs','Identify Data Exfiltration IOCs','Forensics and Logs','Advanced',300,'DNS and outbound web logs show subtle exfiltration over several days.','Custom Docker Lab','webkeet/logs-lab:latest','webkeet/blue/exfil',50,'WebKeet Blue Team'),
('deobfuscate-js','Deobfuscate a JavaScript Payload','Reverse Engineering and Misc','Intermediate',200,'Unpack an obfuscated script recovered from a compromised page.','Custom Docker Lab','webkeet/reverse-lab:latest','webkeet/reverse/js',30,'WebKeet Lab Team'),
('hidden-admin-endpoint','Hidden Admin Endpoint','Reverse Engineering and Misc','Beginner',100,'A single-page app references an admin API in its bundle but hides the UI.','Custom Docker Lab','webkeet/hidden-endpoint:latest','webkeet/reverse/hidden',25,'WebKeet Lab Team'),
('source-map-secrets','Leaked Source Map Secrets','Reverse Engineering and Misc','Beginner',100,'A production build shipped its source map.','Custom Docker Lab','webkeet/source-map:latest','webkeet/reverse/sourcemap',25,'WebKeet Lab Team')
) AS v(slug,title,category,diff,pts,descr,engine,img,path,mins,author)
JOIN (SELECT DISTINCT ON (name) id, name FROM public.lab_authors ORDER BY name, created_at) a ON a.name=v.author
ON CONFLICT (slug) DO UPDATE SET title=EXCLUDED.title,category=EXCLUDED.category,difficulty=EXCLUDED.difficulty,points=EXCLUDED.points,description=EXCLUDED.description,engine=EXCLUDED.engine,docker_image=EXCLUDED.docker_image,lesson_path=EXCLUDED.lesson_path,estimated_minutes=EXCLUDED.estimated_minutes,author_id=EXCLUDED.author_id;

INSERT INTO public.path_labs (path_id,lab_slug,position) SELECT p.id,v.lab,v.pos FROM (VALUES ('web-application-security-fundamentals','sql-injection-fundamentals',0),('web-application-security-fundamentals','reflected-xss',1),('web-application-security-fundamentals','csrf-profile-update',2),('web-application-security-fundamentals','idor-invoice',3),('web-application-security-fundamentals','path-traversal-download',4),('web-application-security-fundamentals','open-redirect',5),('web-application-security-fundamentals','clickjacking-basics',6),('web-application-security-fundamentals','stored-xss-reviews',7),('web-application-security-fundamentals','blind-sqli-time',8),('web-application-security-fundamentals','ssrf-metadata',9),('api-security','bola-crapi',0),('api-security','mass-assignment',1),('api-security','rate-limit-bypass',2),('api-security','jwt-none-algorithm',3),('api-security','graphql-introspection',4),('api-security','oauth-redirect-uri',5),('cloud-security-basics','exposed-bucket',0),('cloud-security-basics','git-secrets',1),('cloud-security-basics','iam-over-permissive',2),('cloud-security-basics','docker-socket',3),('cloud-security-basics','ssrf-metadata',4),('cloud-security-basics','source-map-secrets',5),('linux-privilege-escalation','nmap-discovery',0),('linux-privilege-escalation','suid-abuse',1),('linux-privilege-escalation','cron-hijack',2),('linux-privilege-escalation','sudo-root',3),('linux-privilege-escalation','exfil-iocs',4),('defensive-foundations','access-log-timeline',0),('defensive-foundations','web-shell-upload',1),('defensive-foundations','exfil-iocs',2),('defensive-foundations','scr-sqli',3),('defensive-foundations','scr-csrf',4),('defensive-foundations','scr-upload',5)) AS v(path,lab,pos) JOIN public.learn_paths p ON p.slug=v.path ON CONFLICT (path_id,lab_slug) DO UPDATE SET position=EXCLUDED.position;